package com.aistock.common.adminmarket;
import java.time.*;import org.junit.jupiter.api.Test;import org.springframework.util.*;import static org.junit.jupiter.api.Assertions.*;
class AdminMarketQueryTest {
 private final Clock clock=Clock.fixed(Instant.parse("2026-10-22T04:00:00Z"),ZoneOffset.UTC);
 private static MultiValueMap<String,String> q(String... values){var q=new LinkedMultiValueMap<String,String>();for(int i=0;i<values.length;i+=2)q.add(values[i],values[i+1]);return q;}
 @Test void defaultWindowUsesShanghaiNinetyInclusiveDays(){var w=AdminMarketQuery.detail(q(),clock);assertEquals(LocalDate.parse("2026-07-25"),w.from());assertEquals(LocalDate.parse("2026-10-22"),w.to());assertEquals(1,AdminMarketQuery.listing(q()).page());assertEquals(20,AdminMarketQuery.history(q()).size());}
 @Test void pairedStrictBoundedDates(){assertDoesNotThrow(()->AdminMarketQuery.detail(q("from","2025-10-22","to","2026-10-22"),clock));assertDoesNotThrow(()->AdminMarketQuery.detail(q("from","2026-10-22","to","2026-10-22"),clock));for(var bad:new String[][]{{"from","2025-10-21","to","2026-10-22"},{"from","2026-02-30","to","2026-03-01"},{"from","1989-12-31","to","1990-01-01"},{"from","2026-10-23","to","2026-10-23"},{"from","2026-10-22"},{"other","1"},{"from","2026-10-22","from","2026-10-22","to","2026-10-22"}})assertThrows(com.aistock.common.BusinessException.class,()->AdminMarketQuery.detail(q(bad),clock));}
 @Test void boundedSingletonListAndHistoryInputs(){assertNull(AdminMarketQuery.listing(q("q","  ")).q());assertEquals("x".repeat(64),AdminMarketQuery.listing(q("q","x".repeat(64))).q());for(var bad:new String[][]{{"size","0"},{"size","51"},{"page","0"},{"page","10001"},{"page","1.0"},{"page"," 1"},{"page","01"},{"provider","unknown"},{"q","x".repeat(65)},{"q","a","q","b"}})assertThrows(com.aistock.common.BusinessException.class,()->AdminMarketQuery.listing(q(bad)));assertThrows(com.aistock.common.BusinessException.class,()->AdminMarketQuery.history(q("page","1")));assertThrows(com.aistock.common.BusinessException.class,()->AdminMarketQuery.history(q("from","2026-01-01")));}
 @Test void exactResourcePathsOnly(){String b="/api/v1/admin/market-data";assertTrue(AdminMarketQuery.readPath(b));assertTrue(AdminMarketQuery.readPath(b+"/SH600030/versions"));assertTrue(AdminMarketQuery.readPath(b+"/SH600030/versions/00000000-0000-0000-0000-000000000001"));for(var bad:new String[]{b+"/",b+"/SH600030",b+"/SH600030/versions/abc",b+"/SH600030/versions/00000000-0000-0000-0000-000000000001/retry"})assertFalse(AdminMarketQuery.readPath(bad));}
}
